import styled, { keyframes } from "styled-components";

/*
 * The /notsubscribed route renders outside any ThemeProvider, so there is no
 * restaurant palette to inherit. This variant is Menugic-branded on purpose.
 */
const ACCENT = "#5700FF";
const ACCENT_SOFT = "#8B5CF6";
const INK = "#14161a";

const rise = keyframes`
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const pulseRing = keyframes`
  0%   { transform: scale(1);   opacity: 0.4; }
  70%  { transform: scale(1.45); opacity: 0; }
  100% { transform: scale(1.45); opacity: 0; }
`;

export const Container = styled.div`
  min-height: 100vh;
  min-height: 100dvh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: linear-gradient(180deg, #f8f6ff 0%, #f3eeff 50%, #f8f6ff 100%);
`;

export const Card = styled.div`
  width: 100%;
  max-width: 460px;
  background: #ffffff;
  border: 1px solid rgba(87, 0, 255, 0.08);
  border-radius: 22px;
  padding: 32px 22px 28px;
  text-align: center;
  box-shadow: 0 14px 38px rgba(87, 0, 255, 0.1);
  animation: ${rise} 0.45s ease-out both;

  @media (min-width: 768px) {
    max-width: 520px;
    padding: 44px 44px 38px;
  }
`;

export const Brand = styled.p`
  margin: 0 0 24px;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.6px;
  background: linear-gradient(90deg, ${ACCENT}, ${ACCENT_SOFT});
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: ${ACCENT};
`;

export const IconBadge = styled.div`
  position: relative;
  width: 64px;
  height: 64px;
  margin: 0 auto 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: ${ACCENT};
  background: rgba(87, 0, 255, 0.08);

  svg {
    width: 28px;
    height: 28px;
  }

  &::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 2px solid ${ACCENT};
    animation: ${pulseRing} 2.6s ease-out infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    &::after {
      animation: none;
      opacity: 0.25;
    }
  }
`;

export const Title = styled.h1`
  margin: 0;
  font-size: 24px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.2px;
  color: ${INK};
  direction: ltr;

  @media (min-width: 768px) {
    font-size: 28px;
  }
`;

export const TitleArabic = styled.p`
  margin: 6px 0 0;
  font-size: 17px;
  font-weight: 600;
  line-height: 1.4;
  color: ${INK};
  opacity: 0.72;
  direction: rtl;
  font-family: "Noto Kufi Arabic", "Arial", sans-serif;

  @media (min-width: 768px) {
    font-size: 19px;
  }
`;

export const Divider = styled.div`
  width: 44px;
  height: 3px;
  border-radius: 3px;
  margin: 20px auto;
  background: ${ACCENT};
  opacity: 0.35;
`;

export const Message = styled.p`
  margin: 0;
  font-size: 14px;
  line-height: 1.65;
  color: ${INK};
  opacity: 0.7;
  direction: ltr;

  @media (min-width: 768px) {
    font-size: 15px;
  }
`;

export const MessageArabic = styled.p`
  margin: 10px 0 0;
  font-size: 14px;
  line-height: 1.8;
  color: ${INK};
  opacity: 0.7;
  direction: rtl;
  font-family: "Noto Kufi Arabic", "Arial", sans-serif;

  @media (min-width: 768px) {
    font-size: 15px;
  }
`;

export const CTAButton = styled.a`
  margin-top: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 14px 20px;
  border-radius: 14px;
  background: linear-gradient(90deg, ${ACCENT}, ${ACCENT_SOFT});
  color: #ffffff;
  text-decoration: none;
  cursor: pointer;
  box-shadow: 0 8px 22px rgba(87, 0, 255, 0.28);
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;

  svg {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
  }

  &:hover {
    transform: translateY(-2px);
    filter: brightness(1.07);
  }

  &:active {
    transform: translateY(0);
  }

  &:focus-visible {
    outline: 3px solid ${ACCENT};
    outline-offset: 3px;
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
    &:hover {
      transform: none;
    }
  }
`;

export const CTALabels = styled.span`
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.3;

  span:first-child {
    font-size: 15px;
    font-weight: 600;
  }

  span:last-child {
    font-size: 13px;
    font-weight: 500;
    opacity: 0.85;
    direction: rtl;
    font-family: "Noto Kufi Arabic", "Arial", sans-serif;
  }
`;
